import { readFile, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const schema = JSON.parse(await readFile(resolve(root, 'contracts/algorithm-v1.json'), 'utf8'))
const outputs = {
  'src/domain/algorithm-protocol.ts': `// Generated by scripts/generate-project-protocol.mjs.\nexport const algorithmProtocol = ${JSON.stringify(schema, null, 2)} as const\n
export interface ProtocolEnvelope { protocol_version: number; request_id: string; run_id: string; step_id: number; input_digest: string; capabilities: typeof algorithmProtocol.capabilities }
export interface AlgorithmRequest extends ProtocolEnvelope { input: { view: unknown; state: Record<string, unknown> } }
export interface AlgorithmResponse extends ProtocolEnvelope { decision: unknown }
`,
  'python/gear/_protocol/generated.py': `# Generated by scripts/generate-project-protocol.mjs.\nimport json\n\nPROTOCOL = json.loads(${JSON.stringify(JSON.stringify(schema))})\n
from typing import Any, TypedDict

class ProtocolEnvelope(TypedDict):
    protocol_version: int
    request_id: str
    run_id: str
    step_id: int
    input_digest: str
    capabilities: dict[str, Any]

class AlgorithmRequest(ProtocolEnvelope):
    input: dict[str, Any]

class AlgorithmResponse(ProtocolEnvelope):
    decision: dict[str, Any]
`,
}
for (const [path, content] of Object.entries(outputs)) {
  if (process.argv.includes('--check')) {
    if ((await readFile(resolve(root, path), 'utf8')) !== content) throw new Error(`Regenerate ${path}`)
  } else await writeFile(resolve(root, path), content)
}
